523	    ) {
524	        let mut progress = ParserProgress::default();
525	
526	        let saved_context = self.recovery_context;
527	        self.recovery_context = self
528	            .recovery_context
529	            .union(RecoveryContext::from_kind(recovery_context_kind));
530	
531	        let mut first_element = true;
532	        let mut trailing_comma_range: Option<TextRange> = None;
533	
534	        loop {
535	            progress.assert_progressing(self);
536	
537	            if recovery_context_kind.is_list_element(self) {
538	                parse_element(self);
539	
540	                // Only unset this when we've completely parsed a single element. This is mainly to
541	                // raise the correct error in case the first element isn't valid and the current
542	                // token isn't a comma. Without this knowledge, the parser would later expect a
543	                // comma instead of raising the context error.
544	                first_element = false;
545	
546	                let maybe_comma_range = self.current_token_range();
547	                if self.eat(TokenKind::Comma) {
548	                    trailing_comma_range = Some(maybe_comma_range);
549	                    continue;
