556	            // # the first element is expected by `parse_list_expression`
557	            // [0]
558	            // [0, 1]
559	            // [0, 1,]
560	            // [0, 1, 2]
561	            // [0, 1, 2,]
562	            if recovery_context_kind.is_regular_list_terminator(self) {
563	                break;
564	            }
